/** How often the screen syncs by itself while it is open. */
const AUTO_SYNC_MS = 30_000

// --- camera ---------------------------------------------------------------
// BarcodeDetector is not in lib.dom yet, so the shape we use is declared here
// rather than pulling in a types package for two methods.

interface DetectedBarcode {
  rawValue: string
}
type DetectorCtor = new (opts?: { formats?: string[] }) => {
  detect(source: CanvasImageSource): Promise<DetectedBarcode[]>
}

function getDetector(): DetectorCtor | undefined {
  const ctor = (globalThis as { BarcodeDetector?: DetectorCtor }).BarcodeDetector
  return ctor && navigator.mediaDevices ? ctor : undefined
}

function useScanner(onFound: (text: string) => void) {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [active, setActive] = useState(false)
  const [failed, setFailed] = useState(false)

  useEffect(() => {
    if (!active) return
    const Ctor = getDetector()
    if (!Ctor) return
    const detector = new Ctor({ formats: ['qr_code'] })
    let cancelled = false
    let stream: MediaStream | undefined

    // 300 ms rather than a rAF loop: a QR held up to a camera is not going
    // anywhere, and this leaves the phone's battery alone.
    const timer = window.setInterval(() => {
      const video = videoRef.current
      if (cancelled || !video || video.readyState < 2) return
      void detector
        .detect(video)
        .then((found) => {
          const raw = found[0]?.rawValue
          if (!raw || cancelled) return
          // Close the camera before handing the code on, so the caller never
          // has to know it is holding the camera open.
          setActive(false)
          onFound(raw)
        })
        .catch(() => {
          /* a frame that will not decode is the normal case, not an error */
        })
    }, 300)

    void (async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'environment' },
        })
        if (cancelled) {
          stream.getTracks().forEach((t) => t.stop())
          return
        }
        if (videoRef.current) {
          videoRef.current.srcObject = stream
          await videoRef.current.play()
        }
      } catch {
        setFailed(true)
        setActive(false)
      }
    })()

    return () => {
      cancelled = true
      window.clearInterval(timer)
      stream?.getTracks().forEach((t) => t.stop())
    }
  }, [active, onFound])

  return { videoRef, active, failed, supported: getDetector() !== undefined, setActive }
}

// --- screen ---------------------------------------------------------------

interface Summary {
  total: number
  byStore: { store: OwnedStore; count: number }[]
}

function errorKey(e: unknown): MessageKey {
  if (e instanceof SyncError) {
    if (e.message === 'offline') return 'sync.err.offline'
    if (e.message.startsWith('relay') || e.message === 'rate limited' || e.message === 'too big') {
      return 'sync.err.relay'
    }
  }
  return 'sync.err.generic'
}

/**
 * The step-by-step, above everything else on the screen.
 *
 * The controls below it are correct but assume you already know what a relay
 * is. Someone opening this screen for the first time needs to be told, in
 * order, what to do — including the one command they have to run once.
 */
function Guide() {
  const { t } = useI18n()
  const [copied, setCopied] = useState(false)
  const CMD = 'npx wrangler deploy'

  return (
    <Card title={t('sync.guide.title')} icon="info" hint={t('sync.guide.hint')}>
      <ol className="guide">
        <li className="guide__step">
          <strong>{t('sync.guide.s1')}</strong>
          <p className="card__hint">{t('sync.guide.s1b')}</p>
          <p className="card__hint">{t('sync.guide.s1c')}</p>
          <div className="guide__cmd">
            <code>{CMD}</code>
            <button
              type="button"
              className="btn btn--ghost btn--sm"
              onClick={() => {
                // clipboard can reject (permissions, insecure context); the
                // command is visible either way, so a failure is not fatal.
                navigator.clipboard?.writeText(CMD).then(
                  () => {
                    setCopied(true)
                    window.setTimeout(() => setCopied(false), 2000)
                  },
                  () => {},
                )
              }}
            >
              {copied ? t('sync.guide.copied') : t('sync.guide.copy')}
            </button>
          </div>
        </li>
        <li className="guide__step">
          <strong>{t('sync.guide.s2')}</strong>
          <p className="card__hint">{t('sync.guide.s2b')}</p>
        </li>
        <li className="guide__step">
          <strong>{t('sync.guide.s3')}</strong>
          <p className="card__hint">{t('sync.guide.s3b')}</p>
        </li>
        <li className="guide__step">
          <strong>{t('sync.guide.s4')}</strong>
          <p className="card__hint">{t('sync.guide.s4b')}</p>
        </li>
      </ol>
      <p className="guide__done">{t('sync.guide.done')}</p>
      <p className="disclaimer">{t('sync.guide.safe')}</p>
    </Card>
  )
}

export default function Sync() {
  const { t, locale } = useI18n()
  const { profile } = useSession()

  const [config, setConfig] = useState<SyncConfig | null>(null)
  const [relayDraft, setRelayDraft] = useState('')
  const [pairingCode, setPairingCode] = useState<string | null>(null)
  const [joinDraft, setJoinDraft] = useState('')
  const [summary, setSummary] = useState<Summary | null>(null)
  const [lastAt, setLastAt] = useState<string | undefined>()
  const [notice, setNotice] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [confirmLeave, setConfirmLeave] = useState(false)
  const inFlight = useRef(false)

  const profileId = profile?.id

  useEffect(() => {
    void (async () => {
      const saved = await loadConfig()
      setConfig(saved)
      setRelayDraft(saved?.relayUrl ?? '')
      setLastAt(await lastSyncAt())
    })()
  }, [])

  useEffect(() => {
    if (!profileId) return
    void syncableSummary(profileId).then(setSummary)
  }, [profileId, lastAt])

  const sync = useCallback(async () => {
    // The interval and the button share this; overlapping runs would both scan
    // and both push the same deltas.
    if (!profileId || inFlight.current) return
    inFlight.current = true
    setBusy(true)
    setError(null)
    try {
      const report = await runSync(profileId)
      setLastAt(report.at)
      setNotice(
        report.applied + report.deleted + report.sent === 0
          ? t('sync.status.quiet')
          : t('sync.status.done', {
              masuk: report.applied + report.deleted,
              keluar: report.sent,
            }),
      )
    } catch (e) {
      setNotice(null)
      setError(t(errorKey(e)))
    } finally {
      inFlight.current = false
      setBusy(false)
    }
  }, [profileId, t])

  useEffect(() => {
    if (!config || !profileId) return
    void sync()
    const timer = window.setInterval(() => void sync(), AUTO_SYNC_MS)
    return () => window.clearInterval(timer)
  }, [config, profileId, sync])

  const join = useCallback(
    async (code: string) => {
      setError(null)
      try {
        const pairing = parsePairing(code)
        const next = newConfig(pairing.relayUrl, pairing.roomId, pairing.keyB64)
        await saveConfig(next)
        setConfig(next)
        setRelayDraft(next.relayUrl)
        setPairingCode(null)
        setJoinDraft('')
        setNotice(t('sync.join.joined'))
      } catch {
        setNotice(null)
        setError(t('sync.join.invalid'))
      }
    },
    [t],
  )


  const scanner = useScanner(useCallback((raw: string) => void join(raw), [join]))

  if (!profile) return null

  async function saveRelay() {
    setError(null)
    try {
      const url = assertRelayUrl(relayDraft)
      setRelayDraft(url)
      if (config) {
        const next = { ...config, relayUrl: url }
        await saveConfig(next)
        setConfig(next)
      }
      setNotice(t('sync.relay.saved'))
    } catch {
      setNotice(null)
      setError(t('sync.relay.invalid'))
    }
  }




  async function createRoom() {
    setError(null)
    let relayUrl: string
    try {
      relayUrl = assertRelayUrl(relayDraft)
    } catch {
      setNotice(null)
      setError(t('sync.relay.missing'))
      return
    }
    const keyB64 = await generateRoomKey()
    const next = newConfig(relayUrl, randomRoomId(), keyB64)
    await saveConfig(next)
    setConfig(next)
    setPairingCode(encodePairing({ roomId: next.roomId, keyB64, relayUrl }))
  }

  async function leave() {
    await forgetRoom()
    setConfig(null)
    setPairingCode(null)
      setConfirmLeave(false)
    setLastAt(undefined)
    setNotice(t('sync.leave.done'))
  }

  return (
    <div className="stack">
      <h1>{t('sync.title')}</h1>
      <p className="card__hint">{t('sync.subtitle')}</p>

      {notice && (
        <p className="banner" role="status">
          <Icon name="info" size={18} />
          {notice}
        </p>
      )}
      {error && (
        <p className="banner banner--danger" role="alert">
          {error}
        </p>
      )}

      {/* One implementation of pairing, shared with Settings. It used to be
          written out inline here as well, and two copies of a one-shot invite
          flow is how one of them quietly loses its guard. The relay field
          below feeds it, so a self-hoster still pairs through the same panel. */}
      <PairPanel relayOverride={relayDraft} onPaired={setConfig} connectedCard={false} />

      <Card title={t('sync.how.title')} icon="shared" hint={t('sync.how.body')}>
        <p className="disclaimer">{t('sync.how.limit')}</p>
      </Card>

      <details className="advanced">
        <summary>{t('sync.advanced')}</summary>
        <div className="stack" style={{ marginTop: 'var(--space-3)' }}>
          <Card title={t('sync.relay.title')} icon="settings" hint={t('sync.relay.hint')}>
            <div className="stack stack--tight">
              <Field label={t('sync.relay.label')} hint={DEFAULT_RELAY ? t('sync.relay.default') : undefined}>
                {(p) => (
                  <input
                    {...p}
                    type="url"
                    inputMode="url"
                    autoComplete="off"
                    placeholder={DEFAULT_RELAY}
                    value={relayDraft}
                    onChange={(e) => setRelayDraft(e.target.value)}
                  />
                )}
              </Field>
              <button type="button" className="btn btn--ghost" onClick={() => void saveRelay()}>
                {t('sync.relay.save')}
              </button>
            </div>
          </Card>
          <Guide />
        </div>
      </details>

      {config ? (
        <>
          <Card title={t('sync.status.title')} icon="shared">
            <dl className="sync__meta">
              <dt>{t('sync.status.room')}</dt>
              <dd>{config.roomId}</dd>
              <dt>{t('sync.status.device')}</dt>
              <dd>{config.deviceId}</dd>
              <dt>{t('sync.status.last')}</dt>
              <dd>{lastAt ? fmtDate(lastAt, 'd MMM yyyy, HH:mm', locale) : t('sync.status.never')}</dd>
            </dl>
            <button
              type="button"
              className="btn btn--block"
              disabled={busy}
              onClick={() => void sync()}
              style={{ marginTop: 'var(--space-3)' }}
            >
              <Icon name="restore" size={18} />
              {busy ? t('sync.status.syncing') : t('sync.status.syncNow')}
            </button>
          </Card>

          {pairingCode && (
            <Card title={t('sync.create.title')} icon="shared" hint={t('sync.create.showing')}>
              <div className="stack stack--tight">
                <QrCode text={pairingCode} label={t('sync.create.qrLabel')} />
                <p className="sync__code">{pairingCode}</p>
                <button
                  type="button"
                  className="btn btn--ghost"
                  onClick={() => {
                    void navigator.clipboard
                      ?.writeText(pairingCode)
                      .then(() => setNotice(t('sync.create.copied')))
                      .catch(() => {
                        /* the code is on screen and selectable either way */
                      })
                  }}
                >
                  <Icon name="export" size={18} />
                  {t('sync.create.copy')}
                </button>
                <p className="disclaimer">{t('sync.create.secret')}</p>
              </div>
            </Card>
          )}

          <Card title={t('sync.leave.title')} icon="unpair" hint={t('sync.leave.hint')}>
            <button
              type="button"
              className="btn btn--danger btn--block"
              onClick={() => setConfirmLeave(true)}
            >
              {t('sync.leave.action')}
            </button>
          </Card>
        </>
      ) : (
        <details className="advanced">
          <summary>{t('sync.qr.summary')}</summary>
          <Card title={t('sync.create.title')} icon="shared" hint={t('sync.create.hint')}>
            <button type="button" className="btn btn--block" onClick={() => void createRoom()}>
              <Icon name="plus" size={18} />
              {t('sync.create.action')}
            </button>
          </Card>

          <Card title={t('sync.join.title')} icon="consent" hint={t('sync.join.hint')}>
            <div className="stack stack--tight">
              {scanner.supported ? (
                <>
                  {scanner.active && (
                    // aria-hidden: a live viewfinder carries nothing a screen
                    // reader can use, and the paste field below is the
                    // equivalent path rather than a lesser one.
                    <video
                      className="sync__scan"
                      ref={scanner.videoRef}
                      muted
                      playsInline
                      aria-hidden="true"
                    />
                  )}
                  <button
                    type="button"
                    className="btn btn--ghost"
                    onClick={() => scanner.setActive(!scanner.active)}
                  >
                    <Icon name="checkin" size={18} />
                    {scanner.active ? t('sync.join.scanStop') : t('sync.join.scan')}
                  </button>
                </>
              ) : (
                <p className="card__hint">{t('sync.join.scanUnsupported')}</p>
              )}
              {scanner.failed && <p className="banner banner--warn">{t('sync.join.cameraFailed')}</p>}

              <Field label={t('sync.join.label')}>
                {(p) => (
                  <textarea
                    {...p}
                    rows={3}
                    autoComplete="off"
                    value={joinDraft}
                    onChange={(e) => setJoinDraft(e.target.value)}
                  />
                )}
              </Field>
              <button
                type="button"
                className="btn"
                disabled={!joinDraft.trim()}
                onClick={() => void join(joinDraft)}
              >
                {t('sync.join.action')}
              </button>
            </div>
          </Card>
        </details>
      )}

      <Card title={t('sync.scope.title')} icon="private" hint={t('sync.scope.hint')}>
        {summary && summary.total > 0 ? (
          <>
            <ul className="list">
              {summary.byStore.map((s) => (
                <li key={s.store} className="list__item">
                  <Icon name="shared" size={18} />
                  <span className="grow">{t(`sync.store.${s.store}` as MessageKey)}</span>
                  <span className="chip">{s.count}</span>
                </li>
              ))}
            </ul>
            <p className="card__hint" style={{ marginTop: 'var(--space-2)' }}>
              {t('sync.scope.total', { count: summary.total })}
            </p>
          </>
        ) : (
          <EmptyState
            icon="private"
            title={t('sync.scope.empty')}
            hint={t('sync.scope.emptyHint')}
          />
        )}
      </Card>

      <Card title={t('sync.privacy.title')} icon="shield">
        <div className="stack stack--tight">
          <p className="card__hint">{t('sync.privacy.body')}</p>
          <p className="card__hint">{t('sync.privacy.relay')}</p>
          <p className="disclaimer">{t('sync.privacy.key')}</p>
        </div>
      </Card>

      <Sheet open={confirmLeave} onClose={() => setConfirmLeave(false)} title={t('sync.leave.confirm')}>
        <div className="stack">
          <p className="banner banner--warn">{t('sync.leave.hint')}</p>
          <button type="button" className="btn btn--danger btn--block" onClick={() => void leave()}>
            {t('sync.leave.action')}
          </button>
          <button
            type="button"
            className="btn btn--ghost btn--block"
            onClick={() => setConfirmLeave(false)}
          >
            {t('common.cancel')}
          </button>
        </div>
      </Sheet>
    </div>
  )
}
