/**
 * A small QR encoder — byte mode, error correction level L, versions 1–9.
 *
 * Why hand-rolled: pairing is the one screen where the other phone's camera is
 * the input device, and the alternative was a dependency for a feature whose
 * whole promise is "no cloud, no accounts, nothing you did not choose". Nine
 * versions at level L carry 232 bytes, and a pairing code is about 140, so the
 * general-purpose 3 000-line encoders buy nothing here.
 *
 * Deliberately not supported: numeric/alphanumeric/kanji modes (a pairing code
 * is base64url and mixed case, so byte mode is what it would pick anyway),
 * levels M/Q/H, and versions 10+ (they need a 16-bit character count and
 * unequal block lengths). `encodeQr` throws rather than guessing if a caller
 * ever hands it something bigger.
 *
 * Reference: ISO/IEC 18004. The layout order (function patterns, then data
 * zigzag, then mask, then format bits) follows the same structure as Nayuki's
 * public-domain reference implementation, which is the clearest statement of
 * the spec's placement rules.
 */

const MIN_VERSION = 1
const MAX_VERSION = 9

/**
 * Level-L capacity tables, indexed by version - 1. `TOTAL` is not used by the
 * encoder; it is here so the test can check the other three against the totals
 * printed in the spec, because a single mistyped digit would produce a QR that
 * looks perfectly fine and scans as garbage.
 */
export const LEVEL_L = {
  DATA_CODEWORDS: [19, 34, 55, 80, 108, 136, 156, 194, 232],
  ECC_PER_BLOCK: [7, 10, 15, 20, 26, 18, 20, 24, 30],
  BLOCKS: [1, 1, 1, 1, 1, 2, 2, 2, 2],
  TOTAL: [26, 44, 70, 100, 134, 172, 196, 242, 292],
} as const

const { DATA_CODEWORDS, ECC_PER_BLOCK, BLOCKS } = LEVEL_L
/** Alignment pattern centres. Version 1 has none. */
const ALIGNMENT: number[][] = [
  [],
  [6, 18],
  [6, 22],
  [6, 26],
  [6, 30],
  [6, 34],
  [6, 22, 38],
  [6, 24, 42],
  [6, 26, 46],
]

export class QrTooLong extends Error {}

// --- GF(256) --------------------------------------------------------------

const EXP = new Uint8Array(512)
const LOG = new Uint8Array(256)
{
  let x = 1
  for (let i = 0; i < 255; i++) {
    EXP[i] = x
    LOG[x] = i
    x <<= 1
    if (x & 0x100) x ^= 0x11d // the QR primitive polynomial
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255]!
}

export function gfMul(a: number, b: number): number {
  if (a === 0 || b === 0) return 0
  return EXP[LOG[a]! + LOG[b]!]!
}

function rsGenerator(degree: number): number[] {
  let poly = [1]
  for (let i = 0; i < degree; i++) {
    // poly *= (x + alpha^i), with index 0 holding the leading coefficient.
    const next = new Array<number>(poly.length + 1).fill(0)
    for (let j = 0; j < poly.length; j++) {
      next[j] = next[j]! ^ poly[j]!
      next[j + 1] = next[j + 1]! ^ gfMul(poly[j]!, EXP[i]!)
    }
    poly = next
  }
  return poly
}

/** Reed–Solomon remainder. Exported so the test can check its syndromes. */
export function rsEncode(data: readonly number[], eccLen: number): number[] {
  const gen = rsGenerator(eccLen)
  const rem = new Array<number>(eccLen).fill(0)
  for (const byte of data) {
    const factor = byte ^ rem[0]!
    rem.shift()
    rem.push(0)
    for (let i = 0; i < eccLen; i++) rem[i] = rem[i]! ^ gfMul(gen[i + 1]!, factor)
  }
  return rem
}

// --- BCH ------------------------------------------------------------------

function bch(data: number, generator: number, bits: number): number {
  let rem = data
  for (let i = 0; i < bits; i++) {
    rem = (rem << 1) ^ ((rem >>> (bits - 1)) * generator)
  }
  return rem & ((1 << bits) - 1)
}

/** 15-bit format information for level L and the given mask. */
export function formatBits(mask: number): number {
  const data = (0b01 << 3) | mask // 01 = level L
  return ((data << 10) | bch(data, 0x537, 10)) ^ 0x5412
}

/** 18-bit version information, only present from version 7 up. */
export function versionBits(version: number): number {
  return (version << 12) | bch(version, 0x1f25, 12)
}

// --- bit stream -----------------------------------------------------------

function toCodewords(data: Uint8Array, version: number): number[] {
  const capacity = DATA_CODEWORDS[version - 1]! * 8
  const bits: number[] = []
  const pushBits = (value: number, len: number) => {
    for (let i = len - 1; i >= 0; i--) bits.push((value >>> i) & 1)
  }

  pushBits(0b0100, 4) // byte mode
  pushBits(data.length, 8) // 8-bit count indicator is correct for versions 1–9
  for (const b of data) pushBits(b, 8)

  pushBits(0, Math.min(4, capacity - bits.length)) // terminator
  while (bits.length % 8 !== 0) bits.push(0)

  const codewords: number[] = []
  for (let i = 0; i < bits.length; i += 8) {
    let byte = 0
    for (let j = 0; j < 8; j++) byte = (byte << 1) | bits[i + j]!
    codewords.push(byte)
  }
  // Spec-mandated alternating pad bytes.
  for (let i = 0; codewords.length < DATA_CODEWORDS[version - 1]!; i++) {
    codewords.push(i % 2 === 0 ? 0xec : 0x11)
  }
  return codewords
}

function interleave(codewords: number[], version: number): number[] {
  const numBlocks = BLOCKS[version - 1]!
  const eccLen = ECC_PER_BLOCK[version - 1]!
  const perBlock = DATA_CODEWORDS[version - 1]! / numBlocks

  const dataBlocks: number[][] = []
  const eccBlocks: number[][] = []
  for (let b = 0; b < numBlocks; b++) {
    const block = codewords.slice(b * perBlock, (b + 1) * perBlock)
    dataBlocks.push(block)
    eccBlocks.push(rsEncode(block, eccLen))
  }

  const out: number[] = []
  for (let i = 0; i < perBlock; i++) for (const b of dataBlocks) out.push(b[i]!)
  for (let i = 0; i < eccLen; i++) for (const b of eccBlocks) out.push(b[i]!)
  return out
}

// --- matrix ---------------------------------------------------------------

interface Grid {
  size: number
  modules: boolean[][]
  reserved: boolean[][]
}

function blank(version: number): Grid {
  const size = version * 4 + 17
  return {
    size,
    modules: Array.from({ length: size }, () => new Array<boolean>(size).fill(false)),
    reserved: Array.from({ length: size }, () => new Array<boolean>(size).fill(false)),
  }
}

function set(g: Grid, col: number, row: number, dark: boolean): void {
  g.modules[row]![col] = dark
  g.reserved[row]![col] = true
}

function drawFunctionPatterns(g: Grid, version: number): void {
  const { size } = g

  // Timing patterns first; the finders overwrite their ends.
  for (let i = 0; i < size; i++) {
    set(g, 6, i, i % 2 === 0)
    set(g, i, 6, i % 2 === 0)
  }

  for (const [cx, cy] of [
    [3, 3],
    [size - 4, 3],
    [3, size - 4],
  ] as const) {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const dist = Math.max(Math.abs(dx), Math.abs(dy))
        const x = cx + dx
        const y = cy + dy
        if (x < 0 || y < 0 || x >= size || y >= size) continue
        set(g, x, y, dist !== 2 && dist !== 4) // rings at 0–1 and 3, gap at 2, separator at 4
      }
    }
  }

  const centres = ALIGNMENT[version - 1]!
  for (const cy of centres) {
    for (const cx of centres) {
      // The three corners are finder territory.
      const corner =
        (cx === 6 && cy === 6) ||
        (cx === 6 && cy === size - 7) ||
        (cx === size - 7 && cy === 6)
      if (corner) continue
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) {
          set(g, cx + dx, cy + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1)
        }
      }
    }
  }

  // Reserve the format areas; the real bits go in after masking. Index 6 is
  // skipped in both strips: that module belongs to the timing pattern, which
  // the format information runs around rather than through.
  for (let i = 0; i < 9; i++) {
    if (i === 6) continue
    set(g, 8, i, false)
    set(g, i, 8, false)
  }
  for (let i = 0; i < 8; i++) {
    set(g, size - 1 - i, 8, false)
    set(g, 8, size - 1 - i, false)
  }
  set(g, 8, size - 8, true) // the always-dark module

  if (version >= 7) {
    const bits = versionBits(version)
    for (let i = 0; i < 18; i++) {
      const bit = ((bits >>> i) & 1) === 1
      const a = g.size - 11 + (i % 3)
      const b = Math.floor(i / 3)
      set(g, a, b, bit)
      set(g, b, a, bit)
    }
  }
}

function drawData(g: Grid, data: number[]): void {
  let i = 0
  for (let right = g.size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5 // the vertical timing column is not a data column
    for (let vert = 0; vert < g.size; vert++) {
      for (let j = 0; j < 2; j++) {
        const col = right - j
        const upward = ((right + 1) & 2) === 0
        const row = upward ? g.size - 1 - vert : vert
        if (g.reserved[row]![col] || i >= data.length * 8) continue
        g.modules[row]![col] = ((data[i >>> 3]! >>> (7 - (i & 7))) & 1) === 1
        i++
      }
    }
  }
}

const MASKS: ((r: number, c: number) => boolean)[] = [
  (r, c) => (r + c) % 2 === 0,
  (r) => r % 2 === 0,
  (_r, c) => c % 3 === 0,
  (r, c) => (r + c) % 3 === 0,
  (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
  (r, c) => ((r * c) % 2) + ((r * c) % 3) === 0,
  (r, c) => (((r * c) % 2) + ((r * c) % 3)) % 2 === 0,
  (r, c) => (((r + c) % 2) + ((r * c) % 3)) % 2 === 0,
]

function applyMask(g: Grid, mask: number): void {
  const fn = MASKS[mask]!
  for (let r = 0; r < g.size; r++) {
    for (let c = 0; c < g.size; c++) {
      if (!g.reserved[r]![c] && fn(r, c)) g.modules[r]![c] = !g.modules[r]![c]
    }
  }
}

function drawFormat(g: Grid, mask: number): void {
  const bits = formatBits(mask)
  const bit = (i: number) => ((bits >>> i) & 1) === 1
  for (let i = 0; i <= 5; i++) set(g, 8, i, bit(i))
  set(g, 8, 7, bit(6))
  set(g, 8, 8, bit(7))
  set(g, 7, 8, bit(8))
  for (let i = 9; i < 15; i++) set(g, 14 - i, 8, bit(i))
  for (let i = 0; i < 8; i++) set(g, g.size - 1 - i, 8, bit(i))
  for (let i = 8; i < 15; i++) set(g, 8, g.size - 15 + i, bit(i))
  set(g, 8, g.size - 8, true)
}

/** The spec's four penalty rules. Lower is easier for a camera to read. */
function penalty(g: Grid): number {
  const { size, modules } = g
  let score = 0

  const line = (get: (i: number) => boolean) => {
    let run = 1
    for (let i = 1; i < size; i++) {
      if (get(i) === get(i - 1)) {
        run++
        if (run === 5) score += 3
        else if (run > 5) score += 1
      } else run = 1
    }
  }
  for (let r = 0; r < size; r++) line((c) => modules[r]![c]!)
  for (let c = 0; c < size; c++) line((r) => modules[r]![c]!)

  for (let r = 0; r < size - 1; r++) {
    for (let c = 0; c < size - 1; c++) {
      const v = modules[r]![c]!
      if (v === modules[r]![c + 1] && v === modules[r + 1]![c] && v === modules[r + 1]![c + 1]) {
        score += 3
      }
    }
  }

  // Finder-lookalikes: 1:1:3:1:1 with four light modules on either side.
  const FINDER = [true, false, true, true, true, false, true, false, false, false, false]
  const matches = (get: (i: number) => boolean, at: number, pattern: boolean[]) =>
    pattern.every((p, k) => get(at + k) === p)
  const scan = (get: (i: number) => boolean) => {
    for (let i = 0; i + 11 <= size; i++) {
      if (matches(get, i, FINDER)) score += 40
      if (matches(get, i, [...FINDER].reverse())) score += 40
    }
  }
  for (let r = 0; r < size; r++) scan((c) => modules[r]![c]!)
  for (let c = 0; c < size; c++) scan((r) => modules[r]![c]!)

  let dark = 0
  for (const row of modules) for (const m of row) if (m) dark++
  const percent = (dark * 100) / (size * size)
  score += Math.floor(Math.abs(percent - 50) / 5) * 10
  return score
}

// --- entry point ----------------------------------------------------------

function pickVersion(byteLength: number): number {
  for (let v = MIN_VERSION; v <= MAX_VERSION; v++) {
    // 2 bytes of overhead: 4-bit mode + 8-bit count, rounded up.
    if (DATA_CODEWORDS[v - 1]! >= byteLength + 2) return v
  }
  throw new QrTooLong(`${byteLength} > ${DATA_CODEWORDS[MAX_VERSION - 1]! - 2}`)
}

/**
 * Returns the module grid, row-major, `true` for dark. Excludes the quiet zone —
 * the renderer adds it, because how much margin to leave is a layout decision.
 */
export function encodeQr(text: string): boolean[][] {
  const data = new TextEncoder().encode(text)
  const version = pickVersion(data.length)
  const codewords = interleave(toCodewords(data, version), version)

  let best: Grid | undefined
  let bestScore = Infinity
  for (let mask = 0; mask < 8; mask++) {
    const g = blank(version)
    drawFunctionPatterns(g, version)
    drawData(g, codewords)
    applyMask(g, mask)
    drawFormat(g, mask)
    const score = penalty(g)
    if (score < bestScore) {
      bestScore = score
      best = g
    }
  }
  return best!.modules
}
